// Direct ElevenLabs audio only. No synthetic substitute is labelled as ElevenLabs.
export class CitySound{
 constructor(){this.enabled=false;this.loaded=false;this.buffers=new Map();this.loops=new Map();this.lastHorn=0;this.lastVoice=0;this.lastFoot=0;this.lastPet=0;this.volume=.55}
 async load(){if(this.loaded)return;const r=await fetch('./audio/manifest.json',{cache:'no-cache'});if(!r.ok)throw Error('Daftar audio belum tersedia.');this.manifest=await r.json();if(this.manifest.provider!=='ElevenLabs'||!this.manifest.clips?.length)throw Error('ElevenLabs belum terhubung. Belum ada aset audio ElevenLabs untuk diputar.');await Promise.all(this.manifest.clips.map(async clip=>{const r=await fetch('./audio/'+clip.file);if(!r.ok)return;let buffer=await this.ctx.decodeAudioData(await r.arrayBuffer());this.buffers.set(clip.id,{buffer,...clip})}));if(!this.buffers.size)throw Error('Aset audio ElevenLabs gagal dimuat.');this.loaded=true}
 async toggle(){if(this.enabled){this.enabled=false;for(let loop of this.loops.values())try{loop.source.stop()}catch{}this.loops.clear();document.querySelector('#audio-status').textContent='Audio nonaktif';return false}if(!this.ctx)this.ctx=new(window.AudioContext||window.webkitAudioContext)();await this.ctx.resume();await this.load();this.enabled=true;document.querySelector('#audio-status').textContent='ElevenLabs · audio spasial';return true}
 play(id,{volume=.5,loop=false,x=0,z=0,positional=false}={}){if(!this.enabled||!this.buffers.has(id))return null;let clip=this.buffers.get(id),source=this.ctx.createBufferSource(),gain=this.ctx.createGain();source.buffer=clip.buffer;source.loop=loop;gain.gain.value=volume*this.volume;source.connect(gain);let panner;if(positional){panner=this.ctx.createPanner();panner.panningModel='HRTF';panner.distanceModel='inverse';panner.refDistance=6;panner.maxDistance=150;panner.rolloffFactor=1.6;panner.positionX.value=x;panner.positionY.value=1.2;panner.positionZ.value=z;gain.connect(panner).connect(this.ctx.destination)}else gain.connect(this.ctx.destination);source.start();return{source,gain,panner}}
 loop(id,on,volume,x,z,positional=true){if(!this.enabled)return;let l=this.loops.get(id);if(!on&&l){l.source.stop();this.loops.delete(id);return}if(on&&!l){l=this.play(id,{volume,loop:true,x,z,positional});if(l)this.loops.set(id,l)}if(l){l.gain.gain.setTargetAtTime(volume*this.volume,this.ctx.currentTime,.3);if(l.panner){l.panner.positionX.value=x;l.panner.positionZ.value=z}}}
 tone(){} // Existing mission hooks intentionally wait for authored ElevenLabs assets.
 speak(text){if(!this.enabled)return;let id=/pulang|Hore/.test(text)?'success':/truk/.test(text)?'rescue-voice':'citizen';this.play(id,{volume:.8})}
 update(t,walking,context){if(!this.enabled||!context)return;let {world,state,selfId,local,yaw}=context,l=this.ctx.listener;if(l.positionX){l.positionX.value=local.x;l.positionY.value=1.7;l.positionZ.value=local.z;l.forwardX.value=-Math.sin(yaw);l.forwardY.value=0;l.forwardZ.value=-Math.cos(yaw);l.upX.value=0;l.upY.value=1;l.upZ.value=0}this.loop('wind',true,.24,0,0,false);let trees=world.assets?.batches.find(b=>b.userData.near)?.userData.instances||[],nearest=trees.reduce((a,b)=>Math.hypot(b.x-local.x,b.z-local.z)<Math.hypot(a.x-local.x,a.z-local.z)?b:a,{x:9999,z:9999});this.loop('birds',Math.hypot(nearest.x-local.x,nearest.z-local.z)<100,.7,nearest.x,nearest.z);this.loop('river',Math.abs(local.x-world.plan.river)<110,.75,world.plan.river,local.z);let cars=world.assets?.carBatches?.[0]?.userData.instances||[],car=cars.reduce((a,b)=>Math.hypot(b.record.x-local.x,b.record.z-local.z)<Math.hypot(a.record.x-local.x,a.record.z-local.z)?b:a,{record:{x:9999,z:9999}}).record;let carDistance=Math.hypot(car.x-local.x,car.z-local.z);this.loop('traffic',carDistance<120,.65,car.x,car.z);if(t-this.lastHorn>5&&carDistance<80){this.lastHorn=t;this.play('horn',{volume:.8,x:car.x,z:car.z,positional:true})}let person=world.npcs.reduce((a,b)=>Math.hypot(b.x-local.x,b.z-local.z)<Math.hypot(a.x-local.x,a.z-local.z)?b:a,{x:9999,z:9999});this.loop('crowd',Math.hypot(person.x-local.x,person.z-local.z)<65,.65,person.x,person.z);if(t-this.lastVoice>22&&Math.hypot(person.x-local.x,person.z-local.z)<15){this.lastVoice=t;this.play('citizen',{volume:.65,x:person.x,z:person.z,positional:true})}this.loop('footsteps',walking,.35,local.x,local.z,false);let p=state.players[selfId],working=p.releaseAt>state.now;this.loop(p.inventory.includes('torch')?'welding':'tools',working,.6,state.m.truck.x,state.m.truck.z);let petDistance=Math.hypot(state.pet.x-local.x,state.pet.z-local.z);if(t-this.lastPet>14&&petDistance<45&&state.phase!=='captured'){this.lastPet=t;let species=state.m.animal;let id='pet-dog';const groups=this.manifest.clips.filter(c=>c.id.startsWith('pet-')&&c.animalIds?.includes(species));if(groups.length)id=groups[0].id;this.play(id,{volume:.6,x:state.pet.x,z:state.pet.z,positional:true})}}
}
